'use strict';
(() => {
  const D = window.LAB;
  const $ = (s, root=document) => root.querySelector(s);
  const $$ = (s, root=document) => [...root.querySelectorAll(s)];
  const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const safeParse = (s, fallback) => {try{return JSON.parse(s)??fallback;}catch{return fallback;}};
  const cacheKey='memoryos-design-room-v1';
  let state={variant:'simple',screen:'capture',detail:'',language:'en',tab:'designs',tool:'browse',method:'element',marks:true,selected:'',mapList:false,person:'ali',menu:false,reference:'home-reference',simpleSearch:false,simpleRecording:false,simpleAbout:false,simpleReminder:false};
  const cached=safeParse(localStorage.getItem(cacheKey),{});
  if(cached.variant==='simple')state.variant='simple';
  if(cached.variant==='simple'&&['capture','people','projects','birthdays','brainmap'].includes(cached.screen))state.screen=cached.screen;
  if(['en','ar'].includes(cached.language))state.language=cached.language;
  let annotations=safeParse(localStorage.getItem(cacheKey+'-feedback'),[]), pending=null, editingId=null, originStack=[], saving=false;
  let targetMark=null, drag=null, activeReference=false, toastTimer;
  const screens={capture:'Home',people:'People',projects:'Projects',birthdays:'Birthdays',brainmap:'BrainMap'};
  const variant=()=>D.variants.find(v=>v.id===state.variant);
  const person=id=>D.people.find(p=>p.id===id)||D.people[0];
  const project=id=>D.projects.find(p=>p.id===id)||D.projects[0];
  const t=v=>state.language==='ar'?(D.translations[v]||v):v;
  const name=o=>state.language==='ar'?o.ar:o.name;
  const part=(id,label)=>`data-part="${id}" data-part-label="${esc(label)}"`;
  const iconPaths={settings:'M9 3h6l1 3 3 1v6l-3 1-1 3H9l-1-3-3-1V7l3-1 1-3M9 10a3 3 0 1 0 6 0 3 3 0 0 0-6 0',menu:'M4 6h16M4 12h16M4 18h16',back:'M15 5l-7 7 7 7',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',plus:'M12 4v16M4 12h16',mic:'M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0V5M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8M17 4a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-4',projects:'M3 7h6l2-3h9a1 1 0 0 1 1 1v14a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V7M3 8h18',birthdays:'M4 10h16v10H4V10M2 7h20v3H2V7M12 7v13M12 7H8a3 3 0 1 1 3-3l1 3M12 7h4a3 3 0 1 0-3-3l-1 3',brainmap:'M12 12L5 5M12 12l7-7M12 12l-7 7M12 12l7 7M9 12a3 3 0 1 0 6 0 3 3 0 0 0-6 0M3 5a2 2 0 1 0 4 0 2 2 0 0 0-4 0M17 5a2 2 0 1 0 4 0 2 2 0 0 0-4 0M3 19a2 2 0 1 0 4 0 2 2 0 0 0-4 0M17 19a2 2 0 1 0 4 0 2 2 0 0 0-4 0',source:'M6 2h9l4 4v16H6V2M14 2v6h5M9 12h7M9 16h7',arrow:'M4 12h16M14 6l6 6-6 6',close:'M5 5l14 14M19 5L5 19'};
  const icon=id=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${iconPaths[id]||iconPaths.plus}" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
  const avatar=(p,size='')=>`<span class="avatar ${p.color} ${size}" aria-hidden="true">${p.initials}</span>`;
  const pill=s=>`<span class="app-pill">${t(s)}</span>`;
  const action=(label,open,extra='')=>`<button class="app-action" data-open="${open}" ${extra}>${label}${icon('arrow')}</button>`;
  const sourceButton=id=>`<button class="app-link" data-open="source:${id}">${t('View source')} ↗</button>`;
  const appSearch=(placeholder='Find a person…')=>`<label class="app-search" ${part('search','Search and discovery')}>${icon('search')}<input type="search" data-app-search aria-label="${esc(placeholder)}" placeholder="${esc(state.language==='ar'?'ابحث في ذكرياتك…':placeholder)}"></label>`;
  const personRow=p=>`<button class="app-row" data-open="person:${p.id}" data-search-item="${esc(p.name+' '+p.ar)}" ${part('person-'+p.id,'Person row: '+p.name)}>${avatar(p)}<span class="grow"><strong><bdi>${name(p)}</bdi></strong><small>${state.language==='ar'?p.arabicTopic:p.topic}</small></span><span aria-hidden="true">↗</span></button>`;
  const sourceRow=(id,label)=>`<button class="app-row" data-open="source:${id}" ${part('source-'+id,'Source excerpt')}><span class="grow"><strong>${esc(label||D.sources[id].title)}</strong><small>${D.sources[id].date} · ${D.sources[id].kind}</small></span>${icon('source')}</button>`;
  const footer=()=>state.variant==='simple'?home.footer():`<button class="app-capture" data-open="capture" ${part('capture','Capture composer')}>${icon('plus')}<span>${state.language==='ar'?'اكتب أي شيء…':'Write anything…'}</span><span class="mic-circle">${icon('mic')}</span></button>`;
  function header(){if(state.variant==='simple')return home.header();return `<div class="app-status" ${part('status','Status and safe area')}><span>9:41</span><span>◔ ▰</span></div><header class="app-brand" ${part('header','App navigation and identity')}><button class="icon-btn" data-app-action="${state.detail?'back':'menu'}" aria-label="${t(state.detail?'Back':'Menu')}">${icon(state.detail?'back':'menu')}</button><span class="app-name">${state.variant==='almanac'?'the memory almanac':state.variant==='cabinet'?'MEMORY / CABINET':state.variant==='focus'?'M E M O R Y O S':'MemoryOS'}</span><span class="sample-label">${t('Sample data')}</span></header>${state.menu?`<nav class="app-menu" aria-label="App sections">${Object.entries(screens).filter(([id])=>state.variant==='simple'||id!=='capture').map(([id,label])=>`<button data-screen="${id}">${icon(id)}${t(label)}</button>`).join('')}<button data-open="capture">${icon('mic')}${t('Capture')}</button></nav>`:''}`;}
  function openDetail(id){discardPending();originStack.push({detail:state.detail,selected:state.selected,scroll:$('#device-scroll').scrollTop});state.detail=id;state.menu=false;renderDesign();$('#device-scroll').scrollTop=0;}
  function goBack(){const prev=originStack.pop();state.detail=prev?.detail||'';if(prev)state.selected=prev.selected;renderDesign();$('#device-scroll').scrollTop=prev?.scroll||0;}
  function renderGraph(style='atlas',peopleOnly=false){
    if(state.mapList&&!peopleOnly)return `<div class="relation-list" ${part('map-list','Equivalent connection list')}>${D.people.slice(0,3).map(personRow).join('')}${D.projects.slice(0,2).map(p=>`<button class="app-row" data-open="project:${p.id}"><span class="grow"><strong>${name(p)}</strong><small>${t(p.status)} · ${person(p.person).name}</small></span>${icon('projects')}</button>`).join('')}${sourceRow('website')}${sourceRow('birthday')}</div>`;
    let points=peopleOnly?[['you',50,48],['ali',25,20],['sara',78,34],['noor',24,78],['omar',76,82]]:style==='circles'?[['you',50,50],['ali',50,13],['sara',86,49],['noor',25,84],['website',15,33],['birthday',73,86]]:style==='cabinet'?[['you',48,48],['ali',23,16],['website',76,22],['sara',19,77],['birthday',73,78]]:[['you',42,48],['ali',20,16],['website',79,37],['sara',22,82],['birthday',76,80]];
    const ids=Object.fromEntries(points.map(p=>[p[0],p]));
    let edges=peopleOnly?[['you','ali'],['you','sara'],['you','noor'],['you','omar']]:[['you','ali'],['you','website'],['ali','website'],['ali','birthday'],['you','sara'],['website','birthday']];
    return `<div class="canvas-map ${peopleOnly?'people-map':''} ${style==='circles'?'ring-map':''} ${style==='cabinet'?'pinboard':''}" ${part('map-canvas',peopleOnly?'People constellation':'Relationship map and node positions')}><svg class="map-edges" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">${edges.filter(([a,b])=>ids[a]&&ids[b]).map(([a,b])=>`<line x1="${ids[a][1]}" y1="${ids[a][2]}" x2="${ids[b][1]}" y2="${ids[b][2]}" ${b==='website'?'stroke-dasharray="4 4"':''}/>`).join('')}</svg>${points.map(([id,x,y])=>{const p=D.people.find(p=>p.id===id);const label=p?name(p):id==='you'?t('You'):id==='website'?(state.language==='ar'?'الموقع':'Website idea'):(state.language==='ar'?'ذكرى ميلاد':'Birthday note');return `<button class="map-node ${p?'person-node':id==='you'?'owner':id==='website'?'idea-node':'source-node'} ${!peopleOnly&&state.selected===id?'selected':''}" style="left:${x}%;top:${y}%" ${peopleOnly&&p?`data-open="person:${id}"`:`data-select-node="${id}"`} aria-label="${esc(label)}" aria-pressed="${state.selected===id}" ${part('node-'+id,'Map node: '+label)}>${p?avatar(p):''}<span>${label}</span></button>`;}).join('')}</div>`;
  }
  function inspector(){const id=state.selected,p=D.people.find(p=>p.id===id);const label=p?name(p):id==='website'?name(project('website')):id==='you'?t('You'):D.sources.birthday.title;const target=p?'person:'+p.id:id==='website'?'project:website':id==='you'?'source:website':'source:birthday';return `<section class="relationship-inspector" ${part('relationship-inspector','Selected relationship details')}><div class="app-eyebrow">${state.language==='ar'?'السياق المرتبط':'CONNECTED CONTEXT'}</div><h3 style="margin-top:8px">${esc(label)}</h3><p>${state.language==='ar'?'هذا الرابط من ذكرى تجريبية. يمكنك فتح المصدر.':id==='website'?'A tentative idea from a conversation with Ali. The source keeps the original wording.':p?'A person connected to a sample conversation and project.':'A sample capture links these records.'}</p><div class="detail-actions">${action(t(p?'Open person':id==='website'?'Open project':'View source'),target)}${sourceButton(id==='birthday'?'birthday':p?.source||'website')}</div></section>`;}
  function mapSwitch(){return `<div class="map-controls" ${part('map-alternative','Map and list switch')}><button data-map-mode="map" class="${!state.mapList?'active':''}">${state.language==='ar'?'الخريطة':'Map'}</button><button data-map-mode="list" class="${state.mapList?'active':''}">${state.language==='ar'?'القائمة':'List'}</button><span class="tiny-caption">${state.language==='ar'?'نفس السجلات، عرض آخر':'Same records, another view'}</span></div>`;}
  function calendar(){return `<div class="month-grid" ${part('calendar','Birthday month calendar')}>${['M','T','W','T','F','S','S'].map(d=>`<span class="weekday">${d}</span>`).join('')}${Array.from({length:42},(_,i)=>{const day=i-4;return day>0&&day<=31?`<${day===12?'button data-open="birthday:ali" class="birthday-day" aria-label="Ali’s birthday, 12 May"':'span'}>${day}</${day===12?'button':'span'}>`:'<span></span>';}).join('')}</div>`;}
  function atlas(){if(state.screen==='people')return `<div class="spatial-head" ${part('hero','Constellation introduction')}><div><p class="app-eyebrow">${state.language==='ar'?'عالمك الصغير':'YOUR SMALL WORLD'}</p><h1>${state.language==='ar'?'الأشخاص،\nمترابطون.':'People,<br>connected.'}</h1></div><span class="count">04</span></div><p class="app-subtitle">${state.language==='ar'?'كل حديث يفتح اتصالاً جديداً.':'Every conversation leaves a connection.'}</p>${appSearch()}${renderGraph('atlas',true)}<div class="context-strip" ${part('recent-context','Recent memory context')}><span>07 NOV</span><p>${state.language==='ar'?'تحدثت مع علي عن فكرة موقع.':'You and Ali talked about a website.'}<br>${sourceButton('website')}</p></div>`;
    if(state.screen==='projects')return `<p class="app-eyebrow">${state.language==='ar'?'مساحات التفكير':'THINKING SPACES'}</p><h1>${t('Projects')}</h1><p class="app-subtitle">${state.language==='ar'?'ما تعمل عليه، وما قد يأتي لاحقاً.':'What you’re working on. What might come next.'}</p>${D.projects.map(p=>`<section class="board-section" data-search-item="${esc(p.name)}" ${part('project-cluster-'+p.id,'Project cluster: '+p.name)}><div class="board-title"><h2>${name(p)}</h2>${pill(p.status)}</div><div class="board-papers"><button class="paper-note" data-open="project:${p.id}"><small>CONTEXT / ${p.number}</small><h3>${state.language==='ar'?person(p.person).ar:person(p.person).name}</h3><p>${p.description}</p></button><button class="paper-note" data-open="source:${p.source}"><small>${t('Ideas to consider')}</small><h3>${p.id==='website'?'A proposal,<br>perhaps.':p.id==='reading'?'Keep the why.':'Start with a story.'}</h3><p>${t(p.status)}</p></button></div></section>`).join('')}`;
    if(state.screen==='birthdays')return `<p class="app-eyebrow">${state.language==='ar'?'تواريخ تستحق التذكر':'A FEW DATES TO REMEMBER'}</p><h1>${t('Birthdays')}</h1><p class="app-subtitle">${state.language==='ar'?'اتصالات صغيرة، في وقتها.':'Small connections, at the right moment.'}</p>${[['ali','MAY','12'],['noor','JUNE','24'],['omar','SEPTEMBER','08']].map(([id,m,d])=>`<section class="date-island" ${part('birthday-island-'+id,'Birthday timeline island')}><p class="app-eyebrow">${m} / 2027</p><div class="date-number">${d}</div><button class="island-person" data-open="birthday:${id}">${avatar(person(id))}<span><strong>${name(person(id))}</strong><small>Birthday · Preview only</small></span></button></section>`).join('')}`;
    return `<p class="app-eyebrow">${state.language==='ar'?'اتبع الفكرة':'FOLLOW THE THOUGHT'}</p><h1>${t('BrainMap')}</h1><p class="app-subtitle">${state.language==='ar'?'أشخاص وأفكار، وسياق يجمعها.':'People, ideas, and the context between.'}</p>${mapSwitch()}${renderGraph('atlas')}<div class="map-legend"><span>─ Stored link</span><span>┄ Tentative connection</span></div>${inspector()}`;
  }
  function almanac(){const folio=`<div class="folio" ${part('folio','Editorial date and folio')}><span>THURSDAY, NOVEMBER 12</span><span>VOL. 01</span></div>`;
    if(state.screen==='people')return `${folio}<p class="app-eyebrow">${t('People')}</p><h1>${state.language==='ar'?'أشخاص،\nوقصص تبقى.':'People,<br>and their stories.'}</h1><p class="app-subtitle">${state.language==='ar'?'ما قلناه، وما نود تذكره.':'The things we said. The things worth keeping.'}</p>${D.people.map((p,i)=>`<button class="story" data-open="person:${p.id}" data-search-item="${esc(p.name+' '+p.ar)}" ${part('story-'+p.id,'Person story composition')}><span class="story-date">${['07','06','04','02'][i]}<br>Nov.</span><span><small>${t(p.group)}</small><h3>${name(p)}</h3><p>${state.language==='ar'?p.arabicTopic:p.topic}</p></span></button>`).join('')}`;
    if(state.screen==='projects')return `${folio}<h1>${state.language==='ar'?'أعمال\nقيد التفكير.':'Works<br>in progress.'}</h1><p class="app-subtitle">${state.language==='ar'?'فصل لكل فكرة.':'A chapter for each unfolding idea.'}</p>${D.projects.map(p=>`<button class="chapter" data-open="project:${p.id}" ${part('chapter-'+p.id,'Project chapter composition')}><span class="chapter-number">Chapter ${p.number}</span><h3>${name(p)}</h3><p>${p.description}</p><footer><span class="app-eyebrow">WITH ${person(p.person).name.split(' ')[0]}</span>${pill(p.status)}</footer></button>`).join('')}`;
    if(state.screen==='birthdays')return `${folio}<h1>${state.language==='ar'?'أيام\nلا تُنسى.':'Days to<br>remember.'}</h1><p class="app-subtitle">${state.language==='ar'?'أعياد ميلاد الأشخاص القريبين.':'For the people who make up your days.'}</p><div class="month-heading"><strong>May</strong><span>2027</span></div>${calendar()}<button class="story" data-open="birthday:ali" ${part('birthday-entry','Birthday as a dated journal entry')}><span class="story-date">12<br>May.</span><span><small>A BIRTHDAY</small><h3>${name(person('ali'))}</h3><p>One date, held with care.<br>No reminder scheduled.</p></span></button><h2>Later in the year</h2>${personRow(person('noor'))}${personRow(person('omar'))}`;
    return `${folio}<h1>${state.language==='ar'?'كيف ترتبط\nالأشياء.':'How things<br>connect.'}</h1><p class="app-subtitle">${state.language==='ar'?'هوامش تقود إلى ذكرى أخرى.':'A margin note can lead to another memory.'}</p><section ${part('outline','Relationship outline and source annotations')}><div class="outline-item"><button data-open="person:ali">${name(person('ali'))}</button><small>A person in your world</small></div><div class="outline-item nested"><button data-open="project:website">${name(project('website'))}</button><small>A tentative idea · linked in a conversation</small></div><div class="outline-item nested"><button data-open="source:website">The conversation</button><small>7 November · original wording</small></div><div class="outline-item"><button data-open="birthday:ali">12 May</button><small>A birthday, mentioned in a note</small></div><div class="outline-item nested"><button data-open="source:birthday">The birthday note</button><small>6 November · source</small></div><div class="outline-item"><button data-open="person:sara">${name(person('sara'))}</button><small>Connected to Reading notes</small></div></section>`;
  }
  function circles(){if(state.screen==='people')return `<p class="app-eyebrow">${state.language==='ar'?'أقرب إلى عالمك':'A LITTLE CLOSER'}</p><h1>${state.language==='ar'?'عالمك\nمن الأشخاص.':'Your world<br>is people.'}</h1>${appSearch('Who are you thinking of?')}<button class="featured-person" data-open="person:ali" ${part('featured-person','Featured person and identity treatment')}>${avatar(person('ali'))}<span><span class="app-eyebrow">LAST IN YOUR THOUGHTS</span><h2>${name(person('ali'))}</h2><p>A website idea.<br>A conversation to remember.</p></span></button><p class="people-group-label">${t('Friends')}</p>${D.people.filter(p=>p.id!=='ali'&&p.group==='Friends').map(p=>`<button class="people-row" data-open="person:${p.id}" ${part('group-person-'+p.id,'Grouped contact row')}>${avatar(p)}<span><strong>${name(p)}</strong><small>${state.language==='ar'?p.arabicTopic:p.topic}</small></span></button>`).join('')}<p class="people-group-label">${t('Family')}</p><button class="people-row" data-open="person:noor" ${part('family-group','Family grouping')}>${avatar(person('noor'))}<span><strong>${name(person('noor'))}</strong><small>${state.language==='ar'?'أرشيف العائلة':'The family archive'}</small></span></button>`;
    if(state.screen==='projects')return `<p class="app-eyebrow">${state.language==='ar'?'أشياء نتشاركها':'THINGS WE SHARE'}</p><h1>${state.language==='ar'?'أفكار،\nمعاً.':'Ideas,<br>together.'}</h1>${D.projects.map(p=>`<button class="project-circle" data-open="project:${p.id}" ${part('people-project-'+p.id,'Participant-first project')}><div class="people-project-head"><span class="stack-avatars">${avatar(person(p.person),'tiny')}<span class="avatar tiny">YO</span></span>${pill(p.status)}</div><h2>${name(p)}</h2><p>${p.description}</p><div class="app-eyebrow" style="margin-top:18px">YOU + ${person(p.person).name.split(' ')[0]}</div></button>`).join('')}`;
    if(state.screen==='birthdays')return `<p class="app-eyebrow">${state.language==='ar'?'تذكر التفاصيل الصغيرة':'REMEMBER THE LITTLE THINGS'}</p><h1>${state.language==='ar'?'أيامهم\nالمميزة.':'Their<br>special days.'}</h1><section class="birthday-feature" ${part('birthday-feature','Person-first birthday feature')}>${avatar(person('ali'))}<p class="app-eyebrow">THE NEXT BIRTHDAY</p><h2>${name(person('ali'))}</h2><p class="birthday-date">May the 12th</p>${action(t('Preview reminder'),'birthday:ali')}<p class="tiny-caption">2027 · No reminder scheduled</p></section><h2>More people, more moments</h2>${D.people.filter(p=>p.id!=='ali').map(p=>`<button class="people-row" data-open="birthday:${p.id}" ${part('birthday-person-'+p.id,'Birthday contact row')}>${avatar(p)}<span><strong>${name(p)}</strong><small>${p.date}</small></span></button>`).join('')}`;
    return `<p class="app-eyebrow">${state.language==='ar'?'حول الأشخاص':'AROUND YOUR PEOPLE'}</p><h1>${state.language==='ar'?'دوائرك\nالقريبة.':'Your inner<br>circles.'}</h1><p class="app-subtitle">${state.language==='ar'?'العلاقات هنا روابط في الذكريات، وليست درجات.':'Connections in your memories, without relationship scores.'}</p>${mapSwitch()}${renderGraph('circles')}${inspector()}`;
  }
  function cabinet(){if(state.screen==='people')return `<p class="app-eyebrow">INDEX / 01</p><h1>${state.language==='ar'?'دليل\nالأشخاص.':'The people<br>index.'}</h1>${appSearch('Find a name or an alias…')}<div class="index-strip" ${part('index-navigation','Alphabet index')}><button class="active" data-index="all">All</button>${['A','N','O','S'].map(c=>`<button data-index="${c}">${c}</button>`).join('')}</div>${D.people.map((p,i)=>`<button class="dossier" data-open="person:${p.id}" data-search-item="${esc(p.name+' '+p.ar)}" ${part('dossier-'+p.id,'Person dossier')}><small>PERSON / 00${i+1}</small><div class="dossier-head">${avatar(p)}<span><h3>${name(p)}</h3><small>${t(p.group)} · ${p.date==='Not added'?'Date not added':p.date}</small></span></div><p>${state.language==='ar'?p.arabicTopic:p.topic}</p></button>`).join('')}`;
    if(state.screen==='projects')return `<p class="app-eyebrow">COLLECTIONS / 02</p><h1>${state.language==='ar'?'مساحات\nلأفكارك.':'A shelf for<br>your ideas.'}</h1><p class="app-subtitle">${state.language==='ar'?'افتح مجموعة لترى السياق.':'Open a collection. Find the context inside.'}</p>${D.projects.map(p=>`<button class="folder" data-open="project:${p.id}" ${part('folder-'+p.id,'Project folder composition')}><span class="app-eyebrow">COLLECTION ${p.number}</span><h2>${name(p)}</h2><p>${p.description}</p><footer><span>${t(p.status).toUpperCase()}</span><span>WITH ${person(p.person).name.split(' ')[0]} ↗</span></footer></button>`).join('')}`;
    if(state.screen==='birthdays')return `<p class="app-eyebrow">DATES / 03</p><h1>${state.language==='ar'?'تواريخ،\nفي مكانها.':'Dates,<br>filed with care.'}</h1>${[['ali','MAY','12'],['noor','JUNE','24'],['omar','SEPTEMBER','08']].map(([id,m,d])=>`<section class="birthday-index" ${part('date-index-'+id,'Date index and birthday slip')}><span class="month-tab">${m} 2027</span><button class="birthday-slip" data-open="birthday:${id}"><span class="app-eyebrow">BIRTHDAY</span><div><strong>${d}</strong></div><h3>${name(person(id))}</h3><small>Preview preferences · Nothing scheduled</small></button></section>`).join('')}<p class="tiny-caption">Sara’s birthday has not been added.</p>`;
    return `<p class="app-eyebrow">CROSS-REFERENCES / 04</p><h1>${state.language==='ar'?'كل شيء،\nمرتبط.':'Everything<br>has a thread.'}</h1><p class="app-subtitle">${state.language==='ar'?'افتح الرابط واعثر على مصدره.':'Pull a thread. Find the source behind it.'}</p>${mapSwitch()}${renderGraph('cabinet')}${inspector()}`;
  }
  function focus(){const p=person(state.person);
    if(state.screen==='people')return `<p class="app-eyebrow">${state.language==='ar'?'مساحة للشخص':'A LITTLE SPACE FOR SOMEONE'}</p><h1>${state.language==='ar'?'بمن\nتفكر؟':'Who’s on<br>your <em>mind?</em>'}</h1><div class="focus-switcher" ${part('person-switcher','Focused person switcher')}>${D.people.map(x=>`<button data-focus-person="${x.id}" class="${p.id===x.id?'active':''}" aria-label="${name(x)}" aria-pressed="${p.id===x.id}">${avatar(x)}</button>`).join('')}</div><section class="focus-person" ${part('focused-person','Immersive person reading surface')}><p class="focus-label">${t(p.group)}</p><h2>${name(p)}</h2><blockquote>${state.language==='ar'?p.arabicTopic:p.topic}</blockquote>${sourceButton(p.source)}<div class="detail-actions">${action(t('Open person'),'person:'+p.id)}</div></section><p class="app-eyebrow" style="margin-top:22px">IN THE SAME CONTEXT</p>${sourceRow(p.source)}`;
    if(state.screen==='projects')return `<p class="app-eyebrow">${state.language==='ar'?'أمسك بخيط الفكرة':'HOLD ON TO THE THOUGHT'}</p><section class="focus-project" ${part('focused-project','Single-project focus surface')}>${pill('Tentative')}<h2>${state.language==='ar'?'مقترح\nالموقع.':'Website<br>proposal.'}</h2><p class="idea">${state.language==='ar'?'قد أحضّر مقترحاً الأسبوع المقبل.':'“I might prepare a proposal next week.”'}</p>${sourceButton('website')}<div class="upcoming-person">${avatar(person('ali'))}<span><p class="focus-label">WITH</p><p>${name(person('ali'))}</p></span></div>${action(t('Open project'),'project:website')}</section><h2>Other contexts</h2>${D.projects.slice(1).map(x=>`<button class="app-row" data-open="project:${x.id}" ${part('other-project-'+x.id,'Secondary project context')}><span class="grow"><strong>${name(x)}</strong><small>${t(x.status)} · ${name(person(x.person))}</small></span>${icon('arrow')}</button>`).join('')}`;
    if(state.screen==='birthdays')return `<p class="app-eyebrow">${state.language==='ar'?'عيد الميلاد القادم':'THE NEXT BIRTHDAY'}</p><div class="big-date" ${part('dominant-date','Large typographic birthday date')}>12<span>May.</span></div><p class="app-subtitle">2027 · ${state.language==='ar'?'تاريخ تجريبي':'A sample date'}</p><div class="upcoming-person" ${part('birthday-identity','Birthday person identity')}>${avatar(person('ali'))}<span><h2>${name(person('ali'))}</h2><p class="app-subtitle">One small thing to remember.</p></span></div>${action(t('Preview reminder'),'birthday:ali')}<p class="app-notice">${t('No reminder scheduled.')}</p><h2>After this</h2>${[['noor','24 June'],['omar','8 September']].map(([id,date])=>`<button class="app-row" data-open="birthday:${id}"><span class="grow"><strong>${name(person(id))}</strong><small>${date} 2027</small></span>${icon('arrow')}</button>`).join('')}`;
    return `<p class="app-eyebrow">${state.language==='ar'?'خيط واحد من ذاكرتك':'ONE THREAD THROUGH YOUR MEMORY'}</p><h1>${state.language==='ar'?'اتبع\nالفكرة.':'Follow<br>the <em>thread.</em>'}</h1><section class="trail" ${part('relation-trail','Step-by-step relationship trail')}><button class="trail-step" data-open="source:website">${t('You')}<small>Captured a thought · 7 November</small></button><button class="trail-step current" data-open="project:website">${name(project('website'))}<small>Tentative idea · not an agreed commitment</small></button><button class="trail-step" data-open="person:ali">${name(person('ali'))}<small>Mentioned in the same conversation</small></button><button class="trail-step" data-open="birthday:ali">12 May<small>A birthday · linked source available</small></button></section>${sourceButton('website')}<h2>Another thread</h2>${personRow(person('sara'))}`;
  }
  function detail(){if(state.variant==='simple')return home.detail();const [type,id]=state.detail.split(':');
    if(type==='person'){const p=person(id);return `<div class="detail-title" ${part('profile-identity','Person detail identity')}>${avatar(p,'large')}<span><p class="app-eyebrow">${t('People')}</p><h1 style="font-size:31px">${name(p)}</h1></span></div><p class="app-subtitle">${state.language==='ar'?p.arabicTopic:p.topic}</p><h2>${state.language==='ar'?'تفاصيل معروفة':'A few things to remember'}</h2><div class="detail-fact" ${part('person-facts','Source-backed profile facts')}><span>${t('Birthdays')}</span><button data-open="birthday:${p.id}">${p.date==='Not added'?t('Birthday not added'):p.date} ↗</button></div><div class="detail-fact"><span>Image</span><span>Initials · no photo supplied</span></div><h2>${t('Related memories')}</h2>${sourceRow(p.source)}<h2>${t('Projects')}</h2><button class="app-row" data-open="project:${p.project}"><span class="grow"><strong>${name(project(p.project))}</strong><small>${t(project(p.project).status)}</small></span>${icon('arrow')}</button><section ${part('guided-question','Optional person question')}><h2>${state.language==='ar'?'أضف سياقك':'In your words'}</h2><label class="app-label">${state.language==='ar'?'كيف تعرف هذا الشخص؟':'How do you know this person?'}<textarea id="sample-answer" placeholder="${state.language==='ar'?'الإجابة اختيارية':'An optional answer…'}"></textarea></label><button class="app-action" data-app-action="answer">${state.language==='ar'?'معاينة الإجابة':'Preview answer'}</button><p id="answer-status" class="app-notice" aria-live="polite"></p></section>`;}
    if(type==='project'){const p=project(id);return `<p class="app-eyebrow">${t('Projects')} / ${p.number}</p><h1 ${part('project-detail-title','Project identity and status')}>${name(p)}</h1>${pill(p.status)}<p class="app-subtitle" style="margin-top:15px">${p.description}</p><section ${part('plan','Agreed plan versus tentative wording')}><h2>${t('Current plan')}</h2><p>${t(p.plan)}</p><h2>${t('Ideas to consider')}</h2><div class="source-block">${state.language==='ar'&&id==='website'?'قد أحضّر مقترحاً الأسبوع المقبل.':esc(p.idea)}</div>${sourceButton(p.source)}</section><h2>${t('People')}</h2>${personRow(person(p.person))}<h2>${t('Related memories')}</h2>${sourceRow(p.source)}<div class="detail-actions">${action(state.language==='ar'?'أضف فكرة':'Add a thought','capture:'+p.id)}</div>`;}
    if(type==='source'){const s=D.sources[id]||D.sources.website;return `<p class="app-eyebrow">${state.language==='ar'?'المصدر الأصلي':'THE ORIGINAL SOURCE'}</p><h1 ${part('source-heading','Source identity')}>${esc(s.title)}</h1><p class="app-subtitle">${s.date}<br>${s.kind}</p><div class="source-block" ${part('original-excerpt','Original source text')} dir="auto">${esc(state.language==='ar'?s.ar:s.text)}</div><p class="app-notice">${state.language==='ar'?'مقتطف خيالي للتصميم. لا توجد معلومات شخصية حقيقية.':'Fictional sample. Original wording, without an AI interpretation.'}</p>${action(t('Open person'),'person:'+ (id==='reading'?'sara':id==='archive'?'noor':'ali'))}`;}
    if(type==='birthday'){const p=person(id),has=p.date!=='Not added';return `<p class="app-eyebrow">${t('Birthdays')}</p><div class="detail-title" ${part('birthday-detail-identity','Birthday detail identity')}>${avatar(p,'large')}<h1 style="font-size:31px">${name(p)}</h1></div><h2 style="font-size:36px">${has?p.date:t('Birthday not added')}</h2>${id==='ali'?sourceButton('birthday'):'<p class="app-notice">Fictional date supplied for this design study.</p>'}${has?`<section ${part('reminder-preview','Birthday reminder preview controls')}><h2>${t('Preview reminder')}</h2><p class="app-subtitle">${state.language==='ar'?'اختر التفضيل وشاهد المعاينة فقط.':'Try a preference. This does not schedule anything.'}</p><label class="app-label">${state.language==='ar'?'متى':'When'}<select id="reminder-offset"><option value="0">On the day</option><option value="1">1 day before</option><option value="7">1 week before</option></select></label><label class="app-label">${state.language==='ar'?'الوقت':'Time'}<input id="reminder-time" type="time" value="09:00" required></label><button class="app-action" data-app-action="preview-reminder" data-person="${p.id}">${t('Preview reminder')}</button><p class="app-notice" id="reminder-result" aria-live="polite">${t('No reminder scheduled.')}</p><p class="tiny-caption">Sample clock: 12 Nov 2026 · Asia/Baghdad</p></section>`:'<p class="app-notice">Choose a valid date before a reminder preview. No date is inferred.</p>'}<div class="detail-actions">${action(t('Open person'),'person:'+p.id)}</div>`;}
    return `<p class="app-eyebrow">${t('Capture')}</p><h1>${state.language==='ar'?'مساحة\nلأي فكرة.':'Room for<br>any thought.'}</h1>${id?pill(name(project(id))):''}<label class="app-label">${state.language==='ar'?'ما الذي يدور في بالك؟':'What’s on your mind?'}<textarea id="sample-capture" placeholder="${state.language==='ar'?'اكتب أي شيء…':'Write anything…'}"></textarea></label><button class="app-action" data-app-action="sample-capture">${icon('mic')}${state.language==='ar'?'جرّب التفاعل':'Try sample interaction'}</button><p class="app-notice" id="capture-result" aria-live="polite">No microphone access. This is a design study.</p>`;
  }
  function remember(){localStorage.setItem(cacheKey,JSON.stringify({variant:state.variant,screen:state.screen,language:state.language}));history.replaceState(null,'',`#${state.variant}/${state.screen}${state.detail?'/'+state.detail:''}`);}
  function renderDesign(){
    const scroll=$('#device-scroll').scrollTop;
    $('#app-preview').innerHTML=`<article class="app-shell ${state.variant}" dir="${state.language==='ar'?'rtl':'ltr'}" lang="${state.language}">${header()}<div class="app-main">${state.detail?detail():state.variant==='simple'?home.screen():({atlas,almanac,circles,cabinet,focus}[state.variant])()}</div>${state.variant==='simple'||!state.detail||state.detail.startsWith('person')?footer():''}</article>`;
    if(!state.detail&&state.screen==='people'){$$('[data-open^="person:"]',$('#app-preview')).forEach(el=>{const p=person(el.dataset.open.split(':')[1]);el.dataset.searchItem=p.name+' '+p.ar;});$$('.map-node.person-node',$('#app-preview')).forEach(el=>{const p=D.people.find(p=>el.dataset.part==='node-'+p.id);if(p)el.dataset.searchItem=p.name+' '+p.ar;});}
    $('#language').value=state.language;
    $('#direction-list').innerHTML=D.variants.map(v=>`<button class="direction-button ${v.id===state.variant?'active':''}" data-variant="${v.id}" aria-pressed="${v.id===state.variant}"><span class="direction-number">${v.number}</span><span><strong>${v.name}</strong><small>${v.tone}</small></span><span class="arrow">↗</span></button>`).join('');
    $('#screen-tabs').innerHTML=Object.entries(screens).filter(([id])=>state.variant==='simple'||id!=='capture').map(([id,label])=>`<button data-screen="${id}" aria-pressed="${id===state.screen}" class="${id===state.screen?'active':''}">${label}</button>`).join('');
    $('#caption-name').textContent=state.variant==='simple'?'Sample interface · Home-screen style':'Rejected history · '+variant().name;
    $('#caption-description').textContent=state.variant==='simple'?'Other-screen layouts are proposals.':variant().composition;
    $('#device-scroll').scrollTop=scroll;
    remember();renderTools();renderMarks();renderFeedback();
  }
  function context(isRef=activeReference){const viewDetail=state.detail||(state.variant==='simple'&&state.menu?'menu:'+state.screen:'')||(state.screen==='brainmap'?`map:${state.selected}:${state.mapList?'list':'map'}`:state.variant==='focus'&&state.screen==='people'?`focus:${state.person}`:'');return isRef?{variant:'reference',screen:state.reference,detail:'',language:'en'}:{variant:state.variant,screen:state.screen,detail:viewDetail,language:state.language};}
  const matches=(a,c)=>a.variant===c.variant&&a.screen===c.screen&&a.detail===c.detail&&a.language===c.language;
  function renderTools(){
    $$('[data-tool]').forEach(b=>{b.classList.toggle('active',b.dataset.tool===state.tool);b.setAttribute('aria-pressed',b.dataset.tool===state.tool);});
    $$('[data-ref-tool]').forEach(b=>b.classList.toggle('active',b.dataset.refTool===state.tool));
    $('#selection-method').value=state.method;
    $('#design-canvas').classList.toggle('annotating',state.tool!=='browse');
    $('#reference-canvas').classList.toggle('reference-annotating',state.tool!=='browse');
    $('#show-marks').setAttribute('aria-pressed',state.marks);$('#show-marks').textContent=state.marks?'Marks on':'Marks off';
    $('#tool-hint').textContent=state.tool==='browse'?'Browse the app, or choose Like / Dislike to mark something.':state.method==='element'?`${state.tool==='like'?'Like':state.tool==='dislike'?'Dislike':'Note'} mode: choose an element. Use Tab and Enter for keyboard selection.`:'Drag a rectangle over the design. Add a note in the feedback panel.';
    $('#reference-instruction').textContent=state.tool==='browse'?'Choose Like, Dislike, or Note, then mark the image or text.':'Drag a region, or click an element to mark it. The note editor opens below.';
    $('#annotation-layer').classList.toggle('mark-hidden',!state.marks);$('#reference-layer').classList.toggle('mark-hidden',!state.marks);
    if(state.tool!=='browse'&&state.method==='element'){$$('[data-part]',$('#app-preview')).forEach(el=>{el.setAttribute('tabindex','0');el.setAttribute('role',el.tagName==='BUTTON'?'button':el.getAttribute('role')||'group');});}
    else $$('[data-part][tabindex]',$('#app-preview')).forEach(el=>el.removeAttribute('tabindex'));
  }
  function rectStyle(rect){return `left:${rect.x*100}%;top:${rect.y*100}%;width:${rect.w*100}%;height:${rect.h*100}%`;}
  function currentRect(a,isRef){if(!a.anchor)return a.rect;const canvas=$(isRef?'#reference-canvas':'#design-canvas'),content=$(isRef?'#reference-content':'#app-preview');const el=content.querySelector(`[data-part="${CSS.escape(a.anchor)}"]`);return el?normalizedRect(el.getBoundingClientRect(),canvas):a.rect;}
  function renderMarks(){for(const isRef of [false,true]){const layer=$(isRef?'#reference-layer':'#annotation-layer'),c=context(isRef);const list=annotations.filter(a=>matches(a,c));layer.innerHTML=list.map((a,i)=>`<div class="annotation-box ${a.kind} ${a.id===targetMark?'target':''}" style="${rectStyle(currentRect(a,isRef))}"><button data-edit-note="${a.id}" aria-label="${a.kind}: ${esc(a.label)}">${i+1}</button></div>`).join('')+(pending&&matches(pending,c)?`<div class="annotation-box pending ${pending.kind}" style="${rectStyle(currentRect(pending,isRef))}"></div>`:'');}}
  function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
  function noteCard(a,all=false){const v=a.variant==='reference'?D.references.find(r=>r.id===a.screen)?.name:D.variants.find(v=>v.id===a.variant)?.name;return `<article class="annotation-card"><div class="annotation-head"><span class="reaction-label ${a.kind}">${a.kind==='like'?'＋ LIKE':a.kind==='dislike'?'− DISLIKE':'✎ NOTE'}</span>${a.category?`<span class="category">${esc(a.category)}</span>`:''}</div><p class="context">${esc(v+' / '+(screens[a.screen]||'Reference')+(a.detail?' / '+a.detail:''))} · ${a.language.toUpperCase()}</p><p class="context" style="margin-top:5px">${esc(a.label||'Marked region')}</p>${a.note?`<p class="note-text">${esc(a.note)}</p>`:''}<div class="actions"><button data-jump-note="${a.id}">${all?'Open marked view':'Show region'}</button><button data-edit-note="${a.id}">Edit</button><button data-delete-note="${a.id}">Delete</button></div></article>`;}
  function renderFeedback(){const c=context();const list=annotations.filter(a=>matches(a,c));$('#total-count').textContent=annotations.length;$('#view-count').textContent=list.length;$('#view-notes').innerHTML=list.length?list.map(a=>noteCard(a)).join(''):'<div class="feedback-empty"><b>No marks yet.</b>Choose Like, Dislike, or Note. Select an element or draw a rectangle over what you want to talk about.</div>';if(!pending&&localStorage.getItem(cacheKey+'-draft')){$('#note-editor').hidden=false;$('#note-editor').innerHTML='<div class="editor"><h3>You have an unsaved mark.</h3><p class="context">Resume it before creating another annotation.</p><div class="editor-actions"><button class="primary" data-resume-draft>Resume draft</button><button data-cancel-note>Discard draft</button></div></div>';}renderAllNotes();}
  function renderAllNotes(){const v=$('#filter-variant').value,k=$('#filter-kind').value;const list=annotations.filter(a=>(v==='all'||a.variant===v)&&(k==='all'||a.kind===k));$('#all-notes').innerHTML=list.length?list.map(a=>noteCard(a,true)).join(''):'<div class="feedback-empty"><b>No feedback in this view.</b>Your saved likes, dislikes, and notes will appear here.</div>';}
  function cacheFeedback(){localStorage.setItem(cacheKey+'-feedback',JSON.stringify(annotations));}
  async function request(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store'});const data=await r.json();if(!r.ok)throw Error(data.error||'Local storage request failed');return data;}
  function storage(ok,text){$('#storage-state').textContent=text;$('#storage-state').classList.toggle('error',!ok);}
  async function loadFeedback(){try{const data=await request('/api/feedback');if(!Array.isArray(data.annotations))throw Error('Invalid local feedback store');annotations=data.annotations;cacheFeedback();storage(true,'Feedback saved on this machine');}catch(e){storage(false,'Server unavailable · cached notes only');toast('Local feedback storage is unavailable. Existing cached notes are visible; export a backup.');}renderMarks();renderFeedback();}
  function discardPending(force=false){if(pending&&!force)localStorage.setItem(cacheKey+'-draft',JSON.stringify(pending));if(force)localStorage.removeItem(cacheKey+'-draft');pending=null;editingId=null;$('#note-editor').hidden=true;$('#note-editor').innerHTML='';if($('#ref-note-editor'))$('#ref-note-editor').innerHTML='';}
  function startNote(rect,label,isRef=false,anchor=''){if(pending||localStorage.getItem(cacheKey+'-draft')){toast('Save, resume, or discard your current mark before starting another.');return;}const c=context(isRef);pending={...c,id:'n_'+crypto.randomUUID().replace(/-/g,''),kind:state.tool==='browse'?'note':state.tool,rect,label,anchor,category:'',note:'',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};editingId=null;renderEditor();renderMarks();}
  function editorContainer(isRef=false){if(isRef){if(!$('#ref-note-editor')){const d=document.createElement('div');d.id='ref-note-editor';$('#reference-review').append(d);}return $('#ref-note-editor');}return $('#note-editor');}
  function renderEditor(){if(!pending)return;if(pending.variant!=='reference')$('#designs-tab').classList.add('notes-open');const isRef=pending.variant==='reference',container=editorContainer(isRef);container.hidden=false;container.innerHTML=`<form class="editor" id="feedback-form"><h3>${editingId?'Edit':'Add'} feedback</h3><p class="context" style="font-size:10px">${esc(pending.label)}</p><label>Reaction<select name="kind">${['like','dislike','note'].map(k=>`<option value="${k}" ${pending.kind===k?'selected':''}>${k==='like'?'Like':k==='dislike'?'Dislike':'Note'}</option>`).join('')}</select></label><label>Category (optional)<select name="category"><option value="">Uncategorized</option>${D.categories.map(c=>`<option ${pending.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label>Your note (optional)<textarea name="note" maxlength="6000" placeholder="What do you like? What should change?">${esc(pending.note)}</textarea></label><div class="editor-actions"><button class="primary" type="submit">Save feedback</button><button type="button" data-cancel-note>Cancel</button></div><p class="editor-error" role="alert" hidden></p></form>`;localStorage.setItem(cacheKey+'-draft',JSON.stringify(pending));container.querySelector('textarea').focus({preventScroll:true});if(innerWidth<940||isRef)container.scrollIntoView({behavior:'smooth',block:'center'});}
  async function saveNote(form){if(saving||!pending)return;saving=true;const b=form.querySelector('[type=submit]');b.disabled=true;pending={...pending,kind:form.elements.kind.value,category:form.elements.category.value,note:form.elements.note.value.trim(),updatedAt:new Date().toISOString()};localStorage.setItem(cacheKey+'-draft',JSON.stringify(pending));try{const data=await request('/api/feedback',{operation:'upsert',annotation:pending});annotations=data.annotations;cacheFeedback();storage(true,'Feedback saved on this machine');pending=null;editingId=null;localStorage.removeItem(cacheKey+'-draft');$('#note-editor').hidden=true;$('#note-editor').innerHTML='';if($('#ref-note-editor'))$('#ref-note-editor').innerHTML='';renderMarks();renderFeedback();toast('Feedback saved to this machine.');}catch(e){const error=form.querySelector('.editor-error');error.textContent=e.message+'. Your draft remains in this browser.';error.hidden=false;storage(false,'Could not save feedback');}finally{saving=false;b.disabled=false;}}
  function editNote(id){const a=annotations.find(a=>a.id===id);if(!a)return;jumpNote(id,false);pending=structuredClone(a);editingId=id;renderEditor();renderMarks();}
  async function deleteNote(id){try{const a=annotations.find(a=>a.id===id);if(!a)return;const data=await request('/api/feedback',{operation:'delete',id});annotations=data.annotations;cacheFeedback();if(pending?.id===id)discardPending();renderMarks();renderFeedback();toast('Annotation deleted.');}catch(e){toast('Could not delete: '+e.message);}}
  function applyNoteView(a){state={...state,variant:a.variant,screen:a.screen,detail:a.detail,language:a.language,tab:'designs'};if(a.detail.startsWith('menu:')){state.menu=true;state.detail='';}else state.menu=false;if(a.detail.startsWith('map:')){const [,selected,mode]=a.detail.split(':');state.selected=selected;state.mapList=mode==='list';state.detail='';}if(a.detail.startsWith('focus:')){state.person=a.detail.split(':')[1];state.detail='';}}
  function jumpNote(id,highlight=true){const a=annotations.find(a=>a.id===id);if(!a)return;discardPending();state.tool='browse';if(a.variant==='reference'){setTab('references');openReference(a.screen);}else{applyNoteView(a);originStack=[];setTab('designs');renderDesign();}targetMark=highlight?id:null;renderMarks();const canvas=$(a.variant==='reference'?'#reference-canvas':'#design-canvas');if(a.variant==='reference')window.scrollTo({top:canvas.getBoundingClientRect().top+scrollY+currentRect(a,a.variant==='reference').y*canvas.offsetHeight-150,behavior:'smooth'});else $('#device-scroll').scrollTop=Math.max(0,currentRect(a,a.variant==='reference').y*canvas.offsetHeight-90);renderFeedback();if(a.variant!=='reference'&&innerWidth<940)$('.preview-top').scrollIntoView({behavior:'smooth',block:'start'});}
  function setTab(tab){state.tab=tab;activeReference=tab==='references'&&!$('#reference-review').hidden;['designs','references','feedback'].forEach(id=>$('#'+id+'-tab').hidden=id!==tab);$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));if(tab==='feedback')renderAllNotes();if(tab==='designs'){activeReference=false;renderFeedback();}renderTools();}
  function renderReferences(){ $('#reference-list').innerHTML=D.references.map(r=>`<article class="reference-card"><div class="reference-image ${r.image?'':'text-ref'}">${r.image?`<img src="${r.image}" alt="${r.name} official interface reference" loading="lazy" data-ref-image="${r.id}">`:`<small>WRITTEN REFERENCE</small><span>${r.name}<br><i>${r.type}</i></span>`}</div><h2>${r.name}</h2><p class="type">${r.type}</p><p>${r.role}</p><div class="ref-actions"><button data-reference="${r.id}">Explore & annotate</button><a href="${r.url}" target="_blank" rel="noopener noreferrer">Original source ↗</a></div><p class="credit">${r.image?'Official image © '+r.name+'. ':''}${r.review}</p></article>`).join('');const cards=[...$('#reference-list').children];const history=document.createElement('details');history.className='past-research';history.innerHTML='<summary>Rejected designs and earlier research</summary><div class=\"past-directions\">'+D.variants.filter(v=>v.id!=='simple').map(v=>'<button data-variant=\"'+v.id+'\">'+v.name+' · rejected</button>').join('')+'</div><div class=\"reference-grid\"></div>';cards.slice(1).forEach(card=>history.querySelector('.reference-grid').append(card));$('#reference-list').append(history);$$('[data-ref-image]').forEach(img=>img.addEventListener('error',()=>{img.parentElement.classList.add('text-ref');img.parentElement.textContent=D.references.find(r=>r.id===img.dataset.refImage).name+' · Image unavailable';},{once:true}));}
  function openReference(id){discardPending();state.reference=id;activeReference=true;const r=D.references.find(r=>r.id===id);$('#reference-review').hidden=false;$('#reference-title').textContent=r.name+' / '+r.type;$('#reference-content').innerHTML=`${r.image?`<img src="${r.image}" alt="${r.name} official interface reference" ${part('reference-image',r.name+' interface image')}>`:''}<section ${part('reference-principle',r.name+' design pattern')}><h3>${r.name}</h3><p>${esc(r.role)}</p><p><strong>What we’re exploring:</strong> ${esc(r.borrow)}</p><p><strong>Boundary:</strong> ${esc(r.boundary)}</p><p class="credit">${r.image?'Official reference image © '+r.name+'. ':''}${r.review} <a href="${r.url}" target="_blank" rel="noopener noreferrer">Open original source ↗</a></p></section>`;renderMarks();renderTools();renderFeedback();$('#reference-review').scrollIntoView({behavior:'smooth',block:'start'});}
  function exportFeedback(format){const data={schemaVersion:1,exportedAt:new Date().toISOString(),project:'MemoryOS design room',annotations};let content=JSON.stringify(data,null,2),type='application/json',extension='json';if(format==='md'){type='text/markdown';extension='md';content='# MemoryOS design feedback\n\n'+data.exportedAt+'\n\n'+annotations.map(a=>`## ${a.kind.toUpperCase()} · ${a.variant} / ${a.screen}${a.detail?' / '+a.detail:''}\n\n- Language: ${a.language}\n- Category: ${a.category||'Uncategorized'}\n- Element: ${a.label}\n- Region: ${JSON.stringify(a.rect)}\n\n${a.note||'(No note)'}\n`).join('\n');}const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download='memoryos-design-feedback-'+new Date().toISOString().slice(0,10)+'.'+extension;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Feedback export created.');}
  async function importFeedback(file){if(!file)return;try{if(file.size>2_000_000)throw Error('Export exceeds the 2 MB import limit');const data=JSON.parse(await file.text());const result=await request('/api/import',data);annotations=result.annotations;cacheFeedback();renderMarks();renderFeedback();storage(true,'Feedback saved on this machine');toast('Feedback imported. Existing IDs were merged.');}catch(e){toast('Import failed: '+e.message);}$('#import-file').value='';}
  function layerContext(layer){const isRef=layer.id==='reference-layer';return {isRef,canvas:$(isRef?'#reference-canvas':'#design-canvas'),content:$(isRef?'#reference-content':'#app-preview')};}
  function normalizedRect(box,canvas){const b=canvas.getBoundingClientRect(),x=Math.max(0,Math.min(1,(box.left-b.left)/b.width)),y=Math.max(0,Math.min(1,(box.top-b.top)/b.height));return {x,y,w:Math.max(.005,Math.min(1-x,box.width/b.width)),h:Math.max(.005,Math.min(1-y,box.height/b.height))};}
  function elementAt(event,ctx){const layer=event.currentTarget;layer.style.pointerEvents='none';const node=document.elementFromPoint(event.clientX,event.clientY);layer.style.pointerEvents='';const el=node?.closest('[data-part]');return el&&ctx.content.contains(el)?el:ctx.content;}
  for(const layer of [$('#annotation-layer'),$('#reference-layer')]){
    layer.addEventListener('pointerdown',event=>{if(event.target.closest('[data-edit-note]')||state.tool==='browse'||event.button!==0)return;event.preventDefault();const ctx=layerContext(layer);if(state.method==='element'){const el=elementAt(event,ctx);startNote(normalizedRect(el.getBoundingClientRect(),ctx.canvas),el.dataset.partLabel||'Selected area',ctx.isRef,el.dataset.part||'');return;}drag={x:event.clientX,y:event.clientY,layer,ctx,pointer:event.pointerId};layer.setPointerCapture(event.pointerId);const d=document.createElement('div');d.className='annotation-box pending '+state.tool;d.id='drag-preview';layer.append(d);});
    layer.addEventListener('pointermove',event=>{if(!drag||drag.layer!==layer)return;const box={left:Math.min(drag.x,event.clientX),top:Math.min(drag.y,event.clientY),width:Math.abs(event.clientX-drag.x),height:Math.abs(event.clientY-drag.y)};const el=$('#drag-preview');if(el)el.style.cssText=rectStyle(normalizedRect(box,drag.ctx.canvas));});
    layer.addEventListener('pointerup',event=>{if(!drag||drag.layer!==layer)return;const d=drag;drag=null;if(layer.hasPointerCapture(event.pointerId))layer.releasePointerCapture(event.pointerId);const box={left:Math.min(d.x,event.clientX),top:Math.min(d.y,event.clientY),width:Math.abs(event.clientX-d.x),height:Math.abs(event.clientY-d.y)};if(box.width<6&&box.height<6){const el=elementAt(event,d.ctx);startNote(normalizedRect(el.getBoundingClientRect(),d.ctx.canvas),el.dataset.partLabel||'Selected area',d.ctx.isRef,el.dataset.part||'');}else startNote(normalizedRect(box,d.ctx.canvas),'Custom region',d.ctx.isRef);});
    layer.addEventListener('pointercancel',()=>{drag=null;$('#drag-preview')?.remove();});
  }
  document.addEventListener('keydown',event=>{if(event.key==='Escape'&&state.variant==='simple'&&state.menu){state.menu=false;renderDesign();document.querySelector('.simple-header button')?.focus();return;}if(event.key==='Tab'&&state.variant==='simple'&&state.menu){const buttons=[...document.querySelectorAll('.simple-sidebar button')];const first=buttons[0],last=buttons.at(-1);if(event.shiftKey&&event.target===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&event.target===last){event.preventDefault();first.focus();}}if(event.key==='Escape'){discardPending();state.tool='browse';renderTools();renderMarks();}if(event.key==='Enter'&&state.tool!=='browse'&&state.method==='element'&&event.target.matches('[data-part]')){event.preventDefault();const isRef=$('#reference-content').contains(event.target);startNote(normalizedRect(event.target.getBoundingClientRect(),$(isRef?'#reference-canvas':'#design-canvas')),event.target.dataset.partLabel||'Selected element',isRef,event.target.dataset.part||'');}});
  document.addEventListener('click',event=>{
    const b=event.target.closest('button,a.lab-brand');if(!b)return;
    if(b.matches('a.lab-brand')){event.preventDefault();setTab('designs');return;}
    if(b.dataset.editNote){editNote(b.dataset.editNote);return;}
    if(b.dataset.jumpNote){jumpNote(b.dataset.jumpNote);return;}
    if(b.dataset.deleteNote){deleteNote(b.dataset.deleteNote);return;}
    if(b.hasAttribute('data-cancel-note')){discardPending(true);renderMarks();renderFeedback();return;}
    if(b.hasAttribute('data-resume-draft')){const d=safeParse(localStorage.getItem(cacheKey+'-draft'),null);if(!d)return;if(d.variant==='reference'){setTab('references');openReference(d.screen);}else{applyNoteView(d);setTab('designs');renderDesign();}pending=d;editingId=annotations.some(a=>a.id===d.id)?d.id:null;renderEditor();renderMarks();return;}
    if(b.dataset.tab){discardPending();state.tool='browse';setTab(b.dataset.tab);return;}
    if(b.dataset.variant){discardPending();setTab('designs');state.variant=b.dataset.variant;if(state.variant!=='simple'&&state.screen==='capture')state.screen='people';state.detail='';state.menu=false;state.selected=state.variant==='simple'?'':'website';originStack=[];renderDesign();$('#device-scroll').scrollTop=0;return;}
    if(b.dataset.screen){discardPending();state.screen=b.dataset.screen;state.detail='';state.menu=false;state.simpleSearch=false;state.simpleRecording=false;state.simpleAbout=false;state.simpleReminder=false;if(state.variant==='simple')state.selected='';originStack=[];renderDesign();$('#device-scroll').scrollTop=0;return;}
    if(b.dataset.tool||b.dataset.refTool){state.tool=b.dataset.tool||b.dataset.refTool;if(state.tool!=='browse')document.body.classList.add('annotation-tools-open');renderTools();return;}
    if(b.dataset.reference){setTab('references');openReference(b.dataset.reference);return;}
    if(b.id==='close-reference'){discardPending();$('#reference-review').hidden=true;activeReference=false;state.tool='browse';renderTools();return;}
    if(b.id==='view-inspiration'){setTab('references');openReference(state.variant==='simple'?'home-reference':variant().refs[0]);return;}
    if(b.id==='toggle-annotation'){document.body.classList.toggle('annotation-tools-open');b.setAttribute('aria-expanded',document.body.classList.contains('annotation-tools-open'));if(!document.body.classList.contains('annotation-tools-open')){state.tool='browse';renderTools();}return;}
    if(b.id==='toggle-notes'){$('#designs-tab').classList.toggle('notes-open');return;}
    if(b.id==='show-marks'){state.marks=!state.marks;renderTools();return;}
    if(b.id==='export-json'){exportFeedback('json');return;}if(b.id==='export-md'){exportFeedback('md');return;}if(b.id==='import-button'){$('#import-file').click();return;}
    if(b.dataset.open){if(state.tool==='browse')openDetail(b.dataset.open);return;}
    if(b.dataset.selectNode){state.selected=b.dataset.selectNode;renderDesign();return;}
    if(b.dataset.focusPerson){state.person=b.dataset.focusPerson;renderDesign();return;}
    if(b.dataset.mapMode){state.mapList=b.dataset.mapMode==='list';renderDesign();return;}
    if(b.dataset.index){const all=b.dataset.index==='all';$$('.index-strip button').forEach(x=>x.classList.toggle('active',x===b));$$('[data-search-item]').forEach(el=>el.hidden=!all&&!el.dataset.searchItem.startsWith(b.dataset.index));return;}
    const a=b.dataset.appAction;if(state.variant==='simple'&&home.handle(a))return;
    if(a==='menu'){state.menu=!state.menu;renderDesign();if(state.menu)$('.simple-menu-close')?.focus({preventScroll:true});}else if(a==='back')goBack();
    else if(a==='answer'){$('#answer-status').textContent=$('#sample-answer').value.trim()?'Sample answer previewed. No personal record saved.':'Enter an answer, or use Back to skip.';}
    else if(a==='sample-capture'){$('#capture-result').textContent='Sample interaction only. No recording or memory was created.';}
    else if(a==='preview-reminder'){const time=$('#reminder-time');if(!time.reportValidity())return;const p=person(b.dataset.person);const dates={ali:[4,12],noor:[5,24],omar:[8,8]};const [month,day]=dates[p.id]||[4,12];const date=new Date(Date.UTC(2027,month,day-Number($('#reminder-offset').value)));$('#reminder-result').textContent=date.toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'})+' · '+time.value+' · Asia/Baghdad. '+t('No reminder scheduled.');}
  });
  document.addEventListener('submit',event=>{if(event.target.id==='simple-composer'){event.preventDefault();const input=event.target.elements.thought;if(input.value.trim()){state.simpleText='';toast('Sample thought previewed. No memory was saved.');input.value='';}return;}if(event.target.id==='feedback-form'){event.preventDefault();saveNote(event.target);}});
  document.addEventListener('input',event=>{if(event.target.closest('#simple-composer')&&event.target.name==='thought')state.simpleText=event.target.value;if(event.target.hasAttribute('data-app-search')){const q=event.target.value.trim().toLocaleLowerCase();$$('[data-search-item]',$('#app-preview')).forEach(el=>el.hidden=!el.dataset.searchItem.toLocaleLowerCase().includes(q));const empty=document.querySelector('.simple-no-results');if(empty)empty.hidden=[...document.querySelectorAll('#app-preview [data-search-item]')].some(el=>!el.hidden);}if(event.target.closest('#feedback-form')&&pending){const f=event.target.closest('form');pending.note=f.elements.note.value;pending.category=f.elements.category.value;pending.kind=f.elements.kind.value;localStorage.setItem(cacheKey+'-draft',JSON.stringify(pending));}});
  $('#language').addEventListener('change',e=>{discardPending();state.language=e.target.value;renderDesign();});
  $('#selection-method').addEventListener('change',e=>{state.method=e.target.value;renderTools();});
  $('#filter-variant').innerHTML='<option value="all">All directions</option>'+D.variants.map(v=>`<option value="${v.id}">${v.name}</option>`).join('')+'<option value="reference">References</option>';
  $('#filter-variant').addEventListener('change',renderAllNotes);$('#filter-kind').addEventListener('change',renderAllNotes);$('#import-file').addEventListener('change',e=>importFeedback(e.target.files[0]));
  const home=HomeStyle.create({getState:()=>state,D,t,icon,name,person,project,part,esc,openDetail,render:renderDesign,toast});
  const fromHash=decodeURIComponent(location.hash.slice(1)).split('/');if(fromHash[0]==='simple'){state.variant='simple';if(screens[fromHash[1]])state.screen=fromHash[1];if(/^(person|project|source|birthday|capture)(:[a-z]+)?$/.test(fromHash[2]||''))state.detail=fromHash[2];}
  renderReferences();renderDesign();loadFeedback();
  const draft=safeParse(localStorage.getItem(cacheKey+'-draft'),null);if(draft&&draft.variant==='simple'){if(draft.variant==='reference'){setTab('references');openReference(draft.screen);}else if(D.variants.some(v=>v.id===draft.variant)){applyNoteView(draft);renderDesign();}pending=draft;editingId=annotations.some(a=>a.id===draft.id)?draft.id:null;renderEditor();toast('Recovered your unsaved feedback draft.');}
  window.addEventListener('resize',()=>{renderMarks();});
})();
